const { assign } = helpers()

provide('add_edit_form', useForm({
    question_type_id: 1,
    question: '',
    setup: {},
    choices: [],
    rows: [],
    columns: [],
    items: [],
    item1: [],
    item2: [],
    values: []
}, {
    resetOnSuccess: true,
}))



const faIcon = ref({
    trash: faTrashAlt,
    copy: faCopy,
    edit: faEdit,
    chart: faChartBar,
    link: faExternalLinkAlt,
    arrow_left: faArrowLeft,
    cogs: faCogs,
    plus: faPlusSquare,
    sort: faSort
})
const modals = ref({
    question: {
        add_edit: false,
        copy: false,
        delete: false,
        skip_logic: false,
        move_question: false,
        method: 'add',
        data: null
    }
});
let listShowHide = ref([]);

onMounted(() => {
    //    prepareList()
})

onUpdated(() => {
    //added on update to update question list after adding question
    // prepareList()
})

window.addEventListener("scroll", function (event) {
    const el = event.target;
    clearTimeout(el._scrolling);

    el.classList.add("is-scrolling");

    el._scrolling = setTimeout(() => {
        el.classList.remove("is-scrolling");
    }, 2000);
}, true);

const prepareList = () => {
    let tempStore = []
    props.questions.map(item => {
        let renew = { visible: true }
        tempStore.push(renew);
    });
    listShowHide.value = tempStore;
}

const showQuestion = (index) => {
    if (listShowHide.value[index].visible == true) {
        listShowHide.value[index].visible = false;
    } else {
        listShowHide.value[index].visible = true
    }
    console.log(listShowHide.value)
}

const showModal = (table, modal, method, index = -1, name, lang_id) => {
    modals.value[table].method = method;
    modals.value[table].name = name;
    modals.value[table].language_id = lang_id;
    if (index >= 0) {
        modals.value[table].data = assign(usePage().props.questions[index])
        // console.log(modals[table])
    }
    else {
        modals.value[table].data = null
    }

    modals.value[table][modal] = true
}
const closeModal = (table, modal) => {
    modals.value[table][modal] = false
    modals.value[table].data = null
}
const badge = (question) => {
    return question.setup.advanceSkiplogic.enter.length + question.setup.advanceSkiplogic.leave.length
}

function scrollToTop() {
    document.querySelector('#myDIVxxx').scrollTo(0, 0);
}

function scrollToBottom() {
    let el = document.querySelector('#myDIVxxx')
    document.querySelector('#myDIVxxx').scrollTo(0, el.scrollHeight);
}

const offsetScroll = ref(0)

function handleScroll(event) {
    offsetScroll.value = parseInt(event.currentTarget.scrollTop)
}

</script>

